n1.content:
'Overpass: вибірка тільки реальних укриттів (не газони і зупинки).'
query = f'[out:json][timeout:25];
(  node["civil_defence"="shelter"](around:{radius_m},{lat},{lon});
  node["emergency"="shelter"](around:{radius_m},{lat},{lon});
  node["building"="bunker"](around:{radius_m},{lat},{lon});
  node["amenity"="shelter"]["shelter_type"!="picnic_shelter"]["shelter_type"!="public_transport"]["shelter_type"!="gazebo"]["shelter_type"!="lean_to"](around:{radius_m},{lat},{lon});
  way["civil_defence"="shelter"](around:{radius_m},{lat},{lon});
  way["amenity"="shelter"]["shelter_type"!="picnic_shelter"]["shelter_type"!="public_transport"](around:{radius_m},{lat},{lon});
);
out tags center;'
